package main
import("bufio";"crypto/sha256";"encoding/hex";"encoding/json";"fmt";"os";"path/filepath";"regexp";"sort";"strings")
func hs(s string)string{h:=sha256.Sum256([]byte(s));return hex.EncodeToString(h[:])}
var re=regexp.MustCompile(`[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}`)
func clean(v any)any{switch x:=v.(type){case string:m:=map[string]any{"bytes":len(x),"sha256":hs(x)};if ids:=re.FindAllString(x,-1);len(ids)>0{a:=[]string{};for _,id:=range ids{a=append(a,hs(id))};m["embedded_uuid_sha256"]=a};return m;case map[string]any:m:=map[string]any{};for k,z:=range x{m[k]=clean(z)};return m;case []any:a:=[]any{};for _,z:=range x{a=append(a,clean(z))};return a;default:return x}}
func main(){b,e:=os.ReadFile(os.Args[1]);if e!=nil{panic(e)};var r struct{Groups []struct{Session string `json:"session_sha256"`;Agents []string `json:"agents"`}};if json.Unmarshal(b,&r)!=nil{panic("report")};wanted:=map[string]bool{};for _,g:=range r.Groups{for _,a:=range g.Agents{if a=="mybuddy"&&g.Session!=""{wanted[g.Session]=true}}};paths:=[]string{};for _,root:=range strings.Split(os.Args[2],"|"){filepath.WalkDir(root,func(p string,d os.DirEntry,e error)error{if e==nil&&!d.IsDir()&&strings.HasSuffix(d.Name(),".jsonl"){paths=append(paths,p)};return nil})};sort.Strings(paths);rows:=[]any{};found:=map[string]bool{};for _,p:=range paths{base:=filepath.Base(p);ids:=re.FindAllString(base,-1);if len(ids)==0{continue};id:=ids[len(ids)-1];h:=hs(id);if !wanted[h]{continue};f,e:=os.Open(p);if e!=nil{continue};rd:=bufio.NewReader(f);line,e:=rd.ReadBytes('\n');f.Close();if e!=nil&&len(line)==0{continue};var m map[string]any;if json.Unmarshal(line,&m)!=nil{continue};found[h]=true;rows=append(rows,map[string]any{"session_sha256":h,"header":clean(m),"file_extension":filepath.Ext(p)})};missing:=[]string{};for h:=range wanted{if !found[h]{missing=append(missing,h)}};sort.Strings(missing);out,e:=os.Create(os.Args[3]);if e!=nil{panic(e)};defer out.Close();enc:=json.NewEncoder(out);enc.SetIndent("","  ");enc.Encode(map[string]any{"mybuddy_session_hashes":len(wanted),"headers_found":len(rows),"headers":rows,"missing_session_sha256":missing,"scope":"Only first line of matching MyBuddy session JSONL under current workspace session directory; all strings hashed"});fmt.Printf("wanted=%d found=%d missing=%d\n",len(wanted),len(rows),len(missing));for _,a:=range rows{z:=a.(map[string]any);m:=z["header"].(map[string]any);keys:=[]string{};for k:=range m{keys=append(keys,k)};sort.Strings(keys);fmt.Printf("session=%s keys=%s\n",z["session_sha256"],strings.Join(keys,","))}}
